// Whole-account liquidation, audit 98cd2a781. Preview must use eth_call: the Game dispatcher
// delegates a read-only implementation but its ABI deliberately declares the door nonpayable.
import { ethers, sendTx, requireSelf, getProvider } from './contracts.js';
import { CONTRACTS } from './chain-config.js';
import { get } from './store.js';
import { permissionlessReadProvider } from './read-provider.js';
import { hasWalletIds } from '../chain/schema.js';

export const LIQUIDATION_ABI = [
  'function walletIdOf(address player) view returns (uint32)',
  'function resolveAccount(uint32 id,address caller) view returns (address key,address payee,bool authorized)',
  'function previewLiquidateAccount(uint32 id) returns ((uint32 accountId,uint32 buyerId,bool eligible,bool nativeLiquidity,uint256 faceValue,uint256 quoteBudget,uint256 ticketValue,uint256 price))',
  'function liquidateAccount(uint32 id,uint256 minEthOut)',
  'event AccountLiquidated(uint32 indexed accountId,address indexed seller,uint32 indexed buyerId,uint256 price)',
  'error NotApproved()', 'error RngLocked()', 'error Insolvent()', 'error E()',
];
const SDGNRS_ID = 2;
let factory = null;
const pending = new Set();
export function __setLiquidationContractFactoryForTest(value) { factory = value; }
export function __resetLiquidationContractFactoryForTest() { factory = null; }
const contract = runner => factory ? factory(runner) : new ethers.Contract(CONTRACTS.GAME, LIQUIDATION_ABI, runner);
const lower = value => String(value ?? '').toLowerCase();

function normalizeQuote(raw, payee) {
  return {
    supported: true, accountId: Number(raw.accountId ?? raw[0]), buyerId: Number(raw.buyerId ?? raw[1]),
    eligible: Boolean(raw.eligible ?? raw[2]), nativeLiquidity: Boolean(raw.nativeLiquidity ?? raw[3]),
    faceValue: BigInt(raw.faceValue ?? raw[4]), quoteBudget: BigInt(raw.quoteBudget ?? raw[5]),
    ticketValue: BigInt(raw.ticketValue ?? raw[6]), price: BigInt(raw.price ?? raw[7]), payee: lower(payee),
  };
}

export function liquidationUnavailableReason(quote) {
  if (!quote?.supported) return 'Account liquidation is not available on this deployment.';
  if (!quote.accountId) return 'This wallet has no game account to sell.';
  if (quote.price <= 0n) return 'No eligible unprinted future tickets to liquidate.';
  if (!quote.eligible) return 'This account cannot be liquidated: deity holder, acquired account, or locked/ended game.';
  if (quote.buyerId !== SDGNRS_ID) return 'sDGNRS cannot fund this offer right now. Refresh the quote to try again.';
  if (!quote.nativeLiquidity) return 'The game does not have enough native ETH to pay this offer right now.';
  return '';
}

async function quoteFor(c, id, caller) {
  const [raw, account] = await Promise.all([
    c.previewLiquidateAccount.staticCall(id), c.resolveAccount(id, caller),
  ]);
  const quote = normalizeQuote(raw, account.payee ?? account[1]);
  if (quote.accountId !== id) throw new Error('The account changed. Refresh the liquidation quote.');
  return quote;
}

export async function previewAccountLiquidation({ player } = {}) {
  if (!hasWalletIds()) return { supported: false };
  if (!ethers.isAddress(player)) throw new Error('Pick a player to see a liquidation quote.');
  const c = contract(permissionlessReadProvider(getProvider()));
  const id = Number(await c.walletIdOf(player));
  if (!id) return { supported: true, accountId: 0, price: 0n };
  return quoteFor(c, id, player);
}

/** Recheck ownership, explicit quoted ID, buyer and price inside the fresh-signer write gate. */
export async function sellAccountToSdgnrs({ player, accountId, minEthOut } = {}) {
  requireSelf();
  if (!hasWalletIds()) throw new Error('Account liquidation is not available on this deployment.');
  if (get('ui.mode') !== 'self' || lower(player) !== lower(get('connected.address'))) {
    throw new Error('Only the account owner can liquidate. Connect the owner wallet.');
  }
  const id = Number(accountId), minimum = BigInt(minEthOut ?? 0);
  if (!Number.isSafeInteger(id) || id <= 3 || id > 0xffffffff || minimum <= 0n) {
    throw new Error('Load a valid liquidation quote first.');
  }
  const key = `${lower(CONTRACTS.GAME)}:${id}`;
  if (pending.has(key)) throw new Error('This account already has a liquidation pending.');
  pending.add(key);
  try {
    const receipt = await sendTx(async signer => {
      const owner = lower(await signer.getAddress());
      if (owner !== lower(player)) throw new Error('The wallet changed. Refresh the liquidation quote.');
      const c = contract(signer);
      if (Number(await c.walletIdOf(player)) !== id) throw new Error('The account changed. Refresh the liquidation quote.');
      const quote = await quoteFor(c, id, player);
      if (quote.payee !== owner) throw new Error('Only the account owner can liquidate.');
      const reason = liquidationUnavailableReason(quote);
      if (reason) throw new Error(reason);
      if (quote.price < minimum) throw new Error('The offer decreased. Refresh the quote before selling.');
      await c.liquidateAccount.staticCall(id, minimum);
      requireSelf();
      if (get('ui.mode') !== 'self' || lower(get('connected.address')) !== owner) {
        throw new Error('The wallet changed. Refresh the liquidation quote.');
      }
      return c.liquidateAccount(id, minimum);
    }, 'Liquidate game account');
    return { receipt, accountId: id };
  } catch (error) {
    const name = error?.revert?.name ?? error?.errorName;
    const message = { RngLocked: 'Liquidation pauses while the draw is locked. Refresh after it resolves.',
      Insolvent: 'The buyer or game can no longer fund the offer. Refresh the quote.',
      NotApproved: 'Only the account owner can liquidate.',
      E: 'The offer or account eligibility changed. Refresh the quote before selling.' }[name];
    if (message) throw new Error(message, { cause: error });
    throw error;
  } finally { pending.delete(key); }
}
